// Transcribed from solid-js@2.0.0-rc.3's **server** entrypoint,
// `types/server/signals.d.ts:136-143`. The `createStore` overload pair is
// byte-faithful on the argument side, and the point of this fixture is what the
// pair does *not* say: the plain form is `store: T | Store<T>` with no `NoFn`,
// so a function argument satisfies `T extends object` and a one-argument
// `createStore(compute)` type-checks. The option objects and `ServerStoreOptions`
// are reduced because nothing here reads them back, and a reduced *result*
// cannot create a callback row.
export type Store<T> = T;
export type StoreSetter<T> = (next: T) => void;
export type Accessor<T> = () => T;
export type ComputeFunction<Prev, Next extends Prev = Prev> = (previous: Prev) => Next;

export declare function createStore<T extends object>(
  store: T | Store<T>,
  options?: { name?: string; shallow?: boolean }
): [get: Store<T>, set: StoreSetter<T>];
export declare function createStore<T extends object>(
  fn: (store: T) => void | T | Promise<void | T>,
  store: Partial<T> | Store<T>,
  options?: { name?: string; shallow?: boolean }
): [get: Store<T>, set: StoreSetter<T>];

export declare function createMemo<T>(compute: ComputeFunction<undefined | T, T>): Accessor<T>;
